class Solution:
    def minimumChairs(self, s: str) -> int:
        current_people = 0
        max_people = 0

        for event in s:
            if event == 'E':
                current_people += 1
            else:  # event == 'L'
                current_people -= 1

            # Update maximum number of people seen so far
            max_people = max(max_people, current_people)

        return max_people

