class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total_imbalance = 0

        # Consider all possible subarrays
        for i in range(n):
            sorted_subarray = []
            for j in range(i, n):
                # Extend subarray from i to j
                sorted_subarray.append(nums[j])
                sorted_subarray.sort()

