H, W = map(int, input().split())

# Read the grid
grid = []
for _ in range(H):
    grid.append(list(input().strip()))

# Track which cookies are removed (True means removed)
removed = [[False] * W for _ in range(H)]

# Continue until no more cookies can be marked
while True:
    marked = False

    # Check each row for uniformity
    for i in range(H):
        # Get the current row (only non-removed cookies)
        non_removed = []
        for j in range(W):
            if not removed[i][j]:
                non_removed.append(grid[i][j])

        # If row has at least 2 cookies and all have same color
        if len(non_removed) >= 2 and len(set(non_removed)) == 1:
            # Mark all cookies in this row
            for j in range(W):
                if not removed[i][j]:
                    removed[i][j] = True
            marked = True

    # Check each column for uniformity
    for j in range(W):
        # Get the current column (only non-removed cookies)
        non_removed = []
        for i in range(H):
            if not removed[i][j]:
                non_removed.append(grid[i][j])

        # If column has at least 2 cookies and all have same color
        if len(non_removed) >= 2 and len(set(non_removed)) == 1:
            # Mark all cookies in this column
            for i in range(H):
                if not removed[i][j]:
                    removed[i][j] = True
            marked = True

    # If no cookies were marked, we're done
    if not marked:
        break

# Count remaining cookies
remaining = 0
for i in range(H):
    for j in range(W):
        if not removed[i][j]:
            remaining += 1

print(remaining)

