class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        from collections import Counter

        freq_count = Counter(nums)
        n = len(nums)

        # Try each possible number of groups
        for k in range(1, n + 1):
            base_size = n // k
            remainder = n % k

            # Check if k groups work
            valid = True

            # For each frequency, check if it can be distributed
            for freq in freq_count.values():
                # We can have at most 'remainder' groups of size base_size + 1
                # among all values

                # The minimum number of groups needed to store 'freq' elements
                # with maximum group size base_size + 1 is ceil(freq / (base_size + 1))
                if base_size + 1 == 0:
                    # All groups have size 1
                    if freq != 1:
                        valid = False
                        break
                else:
                    min_groups_needed = (freq + base_size) // (base_size + 1)
                    if min_groups_needed > k:
                        valid = False
                        break

            if valid:
                return k

        return n

