class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        from collections import Counter

        freq_count = Counter(nums)
        n = len(nums)

        # Try each possible number of groups
        for k in range(1, n + 1):
            base_size = n // k
            remainder = n % k

            # If all groups have size 1, each frequency must be exactly 1
            if base_size == 0:
                for freq in freq_count.values():
                    if freq != 1:
                        break
                else:
                    return k

            # For each frequency, check if it can be distributed into at most k groups
            # of sizes base or base + 1
            valid = True
            for freq in freq_count.values():
                # We need to find if there exist non-negative integers x, y such that:
                # x * (base + 1) + y * base = freq
                # and x + y <= k

                # We can rewrite: x * (base + 1) + y * base = freq
                # This means x * (base + 1) <= freq, so x <= freq / (base + 1)

                # Try all possible values of x from 0 to min(freq // (base + 1), k)
                max_x = min(freq // (base + 1), k)  # x cannot exceed k
                found = False

                for x in range(max_x + 1):
                    remainder_after_x = freq - x * (base + 1)
                    if remainder_after_x < 0:
                        break
                    # remainder_after_x must be divisible by base
                    if remainder_after_x % base == 0:
                        y = remainder_after_x // base
                        if x + y <= k:
                            found = True
                            break

                if not found:
                    valid = False
                    break

            if valid:
                return k

        return n
